src/extension.ts<pre><code>import * as vscode from 'vscode';
import { marked } from 'marked';

let currentPanel: vscode.WebviewPanel | undefined;

export function activate(context: vscode.ExtensionContext) {
    context.subscriptions.push(
        vscode.commands.registerCommand('mdPreview.open', () =&gt; {
            const editor = vscode.window.activeTextEditor;
            if (!editor || editor.document.languageId !== 'markdown') {
                vscode.window.showErrorMessage('Open a Markdown file first.');
                return;
            }

            if (currentPanel) {
                currentPanel.reveal(vscode.ViewColumn.Beside);
            } else {
                currentPanel = vscode.window.createWebviewPanel(
                    'mdPreview',
                    'Markdown Preview',
                    vscode.ViewColumn.Beside,
                    { enableScripts: true }
                );

                currentPanel.onDidDispose(() =&gt; {
                    currentPanel = undefined;
                }, null, context.subscriptions);
            }

            updatePreview(editor.document);
        })
    );

    // Update preview on document change
    vscode.workspace.onDidChangeTextDocument(event =&gt; {
        if (
            currentPanel &amp;&amp;
            event.document.languageId === 'markdown' &amp;&amp;
            event.document === vscode.window.activeTextEditor?.document
        ) {
            updatePreview(event.document);
        }
    }, null, context.subscriptions);

    // Update preview when switching editors
    vscode.window.onDidChangeActiveTextEditor(editor =&gt; {
        if (
            currentPanel &amp;&amp;
            editor &amp;&amp;
            editor.document.languageId === 'markdown'
        ) {
            updatePreview(editor.document);
        }
    }, null, context.subscriptions);
}

function updatePreview(document: vscode.TextDocument) {
    if (!currentPanel) return;

    const markdown = document.getText();
    const html = marked(markdown);

    currentPanel.webview.html = `
        &lt;!DOCTYPE html&gt;
        &lt;html lang="en"&gt;
        &lt;head&gt;
            &lt;meta charset="UTF-8"&gt;
            &lt;meta http-equiv="Content-Security-Policy"
                content="default-src 'none'; style-src 'unsafe-inline'; img-src https: data:;"&gt;
            &lt;style&gt;
                body {
                    font-family: var(--vscode-font-family);
                    color: var(--vscode-foreground);
                    background: var(--vscode-editor-background);
                    padding: 24px;
                    line-height: 1.6;
                    max-width: 800px;
                    margin: 0 auto;
                }
                code {
                    background: var(--vscode-textCodeBlock-background);
                    padding: 2px 6px;
                    border-radius: 3px;
                    font-family: var(--vscode-editor-font-family);
                }
                pre code {
                    display: block;
                    padding: 16px;
                    overflow-x: auto;
                }
                blockquote {
                    border-left: 3px solid var(--vscode-textBlockQuote-border);
                    margin-left: 0;
                    padding-left: 16px;
                    color: var(--vscode-textBlockQuote-foreground);
                }
                a { color: var(--vscode-textLink-foreground); }
                img { max-width: 100%; }
                table {
                    border-collapse: collapse;
                    width: 100%;
                }
                th, td {
                    border: 1px solid var(--vscode-panel-border);
                    padding: 8px 12px;
                    text-align: left;
                }
            &lt;/style&gt;
        &lt;/head&gt;
        &lt;body&gt;
            ${html}
        &lt;/body&gt;
        &lt;/html&gt;
    `;

    currentPanel.title = `Preview: ${document.fileName.split('/').pop()}`;
}

export function deactivate() {
    currentPanel?.dispose();
}
</code></pre>

